cat > terraform_vpc/locals.tf <<'EOF'
locals {
 common_tags = {
 Environment = var.environment
 ManagedBy = "Terraform"
 Project = var.application_name
 }

 name_prefix = "${var.application_name}-${var.environment}"
}
EOF

cat > terraform_vpc/main.tf <<'EOF'
