args.command:
pwd && ls -la && mkdir -p terraform_vpc && cat > terraform_vpc/terraform.tf <<'EOF'
terraform {
  required_version = ">= 1.14"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 6.0"
    }
  }
}
EOF

cat > terraform_vpc/providers.tf <<'EOF'
provider "aws" {
  region = var.aws_region

  default_tags {
    tags = local.common_tags
  }
}
EOF

cat > terraform_vpc/variables.tf <<'EOF'
variable "application_name" {
  description = "Name of the application owning this infrastructure"
  type        = string
}

variable "aws_region" {
  description = "AWS region where resources will be created"
  type        = string
  default     = "us-west-2"
}

variable "environment" {
  description = "Deployment environment name"
  type        = string

  validation {
    condition     = contains(["dev", "staging", "prod"], var.environment)
    error_message = "Environment must be dev, staging, or prod."
  }
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}
EOF

cat > terraform_vpc/locals.tf <<'EOF'
locals {
  common_tags = {
    Environment = var.environment
    ManagedBy   = "Terraform"
    Project     = var.application_name
  }

  name_prefix = "${var.application_name}-${var.environment}"
}
EOF

cat > terraform_vpc/main.tf <<'EOF'
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-igw"
  })
}
EOF

cat > terraform_vpc/outputs.tf <<'EOF'
output "internet_gateway_id" {
  description = "ID of the internet gateway attached to the VPC"
  value       = aws_internet_gateway.main.id
}

output "vpc_id" {
  description = "ID of the created VPC"
  value       = aws_vpc.main.id
}
EOF

cat > terraform_vpc/.gitignore <<'EOF'
.terraform/
*.tfplan
terraform.tfstate
terraform.tfstate.backup
*.tfvars
EOF

cd terraform_vpc && find . -maxdepth 2 -type f | sort | xargs -I{} sh -c 'echo "--- {}"; sed -n "1,200p" "{}"'
